
#!/usr/bin/env python3
"""BCH Flow V322 — minimalist wallet UI; no financial or database modifications."""
import argparse,base64,hashlib,json,os,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
BACKUP=Path.home()/'Downloads'/'bchflow-v322-minimal-backup'
PAYLOAD={'app_bch_flow/templates/app_bch_flow/wallet_v41/home.html': '', 'app_bch_flow/static/app_bch_flow/css/wallet-minimal-v322.css': '', 'app_bch_flow/static/app_bch_flow/js/wallet-shell-v322.js': ''}
EXPECTED={'app_bch_flow/templates/app_bch_flow/wallet_v41/home.html':'489eee155db41bce2e005cb720191d8d616fd5681af974cec7b1c5458ae956a4'}
DEPENDENCIES=('app_bch_flow/static/app_bch_flow/js/wallet-craft-v321.js','app_bch_flow/static/app_bch_flow/css/wallet-craft-v321.css','app_bch_flow/views/wallet_shell_v320.py')
def sha(b):return hashlib.sha256(b).hexdigest()
def target(rel):
 p=(ROOT/rel).resolve()
 if not p.is_relative_to(ROOT.resolve()):raise ValueError('Unsafe target')
 return p
def plan():
 errors=[];changes={}
 for rel in DEPENDENCIES:
  if not target(rel).is_file():errors.append('Missing V321 dependency: '+rel)
 for rel,encoded in PAYLOAD.items():
  p=target(rel);data=base64.b64decode(encoded)
  if p.is_symlink():errors.append('Symlink blocked: '+rel);continue
  if p.exists():
   old=p.read_bytes()
   if old==data:continue
   if rel not in EXPECTED or sha(old)!=EXPECTED[rel]:errors.append('Existing file mismatch: '+rel);continue
  changes[rel]=data
 return errors,changes
def main():
 parser=argparse.ArgumentParser();group=parser.add_mutually_exclusive_group(required=True)
 for arg in ('check','install','rollback'):group.add_argument('--'+arg,action='store_true')
 args=parser.parse_args()
 if args.rollback:
  manifest_file=BACKUP/'manifest.json'
  if not manifest_file.is_file():sys.exit('No V322 backup')
  manifest=json.loads(manifest_file.read_text())
  for rel,entry in manifest.items():
   p=target(rel)
   if not p.is_file() or sha(p.read_bytes())!=entry['after']:sys.exit('ABORTED: file changed since install: '+rel)
  for rel,entry in manifest.items():
   p=target(rel)
   if entry['before'] is None:p.unlink()
   else:p.write_bytes((BACKUP/'files'/rel).read_bytes())
  print(json.dumps({'status':'ROLLED_BACK','files':len(manifest)}));return
 errors,changes=plan()
 if errors:print(json.dumps({'status':'BLOCKED','errors':errors},indent=2));sys.exit(2)
 if args.check:print(json.dumps({'status':'READY','files_to_change':list(changes)},indent=2));return
 if not changes:print(json.dumps({'status':'ALREADY_INSTALLED'}));return
 if BACKUP.exists():sys.exit('ABORTED: backup directory exists')
 BACKUP.mkdir(parents=True);manifest={}
 try:
  for rel,data in changes.items():
   p=target(rel);old=p.read_bytes() if p.exists() else None
   if old is not None:
    b=BACKUP/'files'/rel;b.parent.mkdir(parents=True,exist_ok=True);b.write_bytes(old)
   manifest[rel]={'before':sha(old) if old is not None else None,'after':sha(data)}
  (BACKUP/'manifest.json').write_text(json.dumps(manifest,indent=2))
  for rel,data in changes.items():
   p=target(rel);p.parent.mkdir(parents=True,exist_ok=True)
   tmp=p.with_name(p.name+'.v322-tmp');tmp.write_bytes(data);os.replace(tmp,p)
  print(json.dumps({'status':'INSTALLED','files':len(changes),'backup':str(BACKUP)},indent=2))
 except Exception:
  for rel,entry in manifest.items():
   p=target(rel)
   if entry['before'] is None:p.unlink(missing_ok=True)
   else:p.write_bytes((BACKUP/'files'/rel).read_bytes())
  raise
if __name__=='__main__':main()
